// File was generated by Claude.
// Tests for the analytic inverse kinematics of the 4R arm (base rotation + planar 3R),
// kinematics::inverse(pos, theta, arm, tool), checked against the general forward kinematics
// kinematics::forward(phi, arm, tool), which returns the full 4x4 pose of the tool frame.
//
// Geometry (DH-style, see arm_geometry.hpp):
//   Arm<T>({0, a_sh, R1, R2}, {h, o_sh, o_el, o_wr})
//     link 0: base column, height h along the base axis
//     link 1: base -> shoulder, twist +90 deg, radial shoulder offset a_sh (0 here), lateral offset o_sh
//     link 2: upper arm R1, lateral offset o_el
//     link 3: forearm R2, lateral offset o_wr
//   Tool<T>(q_x, q_y, q_z): tool point in the tool's own frame (twist applied first):
//     q_z along the approach direction (tool z), q_x along the tool's common normal,
//     q_y along the tool's y-axis, which is the wrist axis for the +90 deg tool twist
//
// Conventions assumed:
//  - forward() returns a pose matrix with the homogeneous 1 at index 0:
//    column 0 rows 1..3 = tool position, column 3 rows 1..3 = tool z (approach direction)
//  - theta: approach angle, 0 = tool pointing straight down; within the arm's plane the tool
//    points along (sin theta, -cos theta), with the plane's horizontal axis oriented towards
//    the target
//  - the solver keeps only configurations with the elbow at or above shoulder height
//
// For every filled solution slot the test checks:
//  1. the tool position equals the target
//  2. the tool's z-axis is the requested approach direction
//  3. the elbow is not below the shoulder
//  4. the branch flags agree with the geometry:
//     reach_front - the arm's plane points towards the target
//     elbow_up    - the elbow lies above the line from shoulder to wrist (within the arm's plane)
// Random targets are generated from random joint angles via forward kinematics, so they are
// reachable by construction, and the original configuration must appear among the solutions.
// Joint positions (shoulder, elbow, wrist) are computed from the arm's own link transforms.

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <numbers>
#include <random>
#include "kinematics/analytic/base+3planar.hpp"
#include "kinematics/general.hpp"

using namespace kinematics;
using arm4R_bnp::Arm;
using arm4R_bnp::Flags;
template<typename T> 
using Tool = ToolLink<T, Twist::Plus90>;

static int failures = 0;
static void check(bool ok, const char* what) { if (!ok) { ++failures; std::printf("FAIL: %s\n", what); } }

static double angle_diff(double a, double b) { return std::remainder(a - b, 2.0 * std::numbers::pi); }

template<std::floating_point T>
struct Geometry {
    T h;                          // base height
    T R1, R2;                     // upper arm, forearm
    T tool_len, tool_cn, tool_lat; // tool along the approach, its common normal, and the wrist axis
    std::array<T, 3> offsets;     // lateral offsets along shoulder, elbow, wrist axes
};

template<std::floating_point T>
Arm<T> make_arm(const Geometry<T>& g)
{
    return Arm<T>({T(0), T(0), g.R1, g.R2}, {g.h, g.offsets[0], g.offsets[1], g.offsets[2]});
}

template<std::floating_point T>
Tool<T> make_tool(const Geometry<T>& g) { return Tool<T>(g.tool_cn, g.tool_lat, g.tool_len); }

template<std::floating_point T>
T total_offset(const Geometry<T>& g) { return g.offsets[0] + g.offsets[1] + g.offsets[2] + g.tool_lat; }

template<std::floating_point T>
double scale_of(const Geometry<T>& g)
{
    return double(g.h + g.R1 + g.R2 + g.tool_len + g.tool_cn + total_offset(g));
}

// Positions of the frame origins after links 1, 2 and 3: on the shoulder, elbow and wrist axes.
template<std::floating_point T>
std::array<std::array<double, 3>, 3> joint_positions(const std::array<T, 4>& phi, const Arm<T>& arm)
{
    std::array<std::array<double, 3>, 3> p{};
    linalg::Matrix<T, 4, 4> m = arm.world_trafo();
    for (std::size_t i = 0; i < 4; ++i) {
        m = m * arm.links()[i].bridge_trafo();
        if (i >= 1) p[i - 1] = {double(m[1, 0]), double(m[2, 0]), double(m[3, 0])};
        m = m * se3_z(phi[i], T(0), T(0), T(0));
    }
    return p;
}

// Horizontal unit vector of the arm's plane after the base rotation, oriented towards the target
static std::array<double, 2> towards_target(double phi0, const std::array<double, 3>& target, bool& front)
{
    const double ex = std::cos(phi0), ey = std::sin(phi0);
    front = target[0] * ex + target[1] * ey > 0;
    const double s = front ? 1.0 : -1.0;
    return {s * ex, s * ey};
}

// Approach angle of a pose: the tool z-axis written as (sin theta * towards, -cos theta)
template<std::floating_point T>
double approach_angle(const linalg::Matrix<T, 4, 4>& pose, double phi0)
{
    const std::array<double, 3> target{double(pose[1, 0]), double(pose[2, 0]), double(pose[3, 0])};
    bool front;
    const auto u = towards_target(phi0, target, front);
    const double horizontal = double(pose[1, 3]) * u[0] + double(pose[2, 3]) * u[1];
    return std::atan2(horizontal, -double(pose[3, 3]));
}

// ------------------------------------------------------------ checks of one solution

struct Errors { double pos = 0, dir = 0; bool below_shoulder = false, wrong_front = false, wrong_elbow = false; };

template<std::floating_point T>
Errors check_solution(const Geometry<T>& g, const Arm<T>& arm, const Tool<T>& tool,
                      const std::array<T, 3>& pos, T theta, const arm4R_bnp::Branch<T>& sol, double side_tol)
{
    Errors e;
    const auto& phi = sol.angles();
    const double scale = scale_of(g);
    const auto pose = forward(phi, arm, tool);

    // 1. position
    e.pos = std::hypot(double(pose[1, 0]) - pos[0], double(pose[2, 0]) - pos[1], double(pose[3, 0]) - pos[2]) / scale;

    // 2. approach direction = tool z-axis
    const std::array<double, 3> target{double(pos[0]), double(pos[1]), double(pos[2])};
    bool front;
    const auto u = towards_target(double(phi[0]), target, front);
    const double s = std::sin(double(theta)), c = std::cos(double(theta));
    e.dir = std::hypot(double(pose[1, 3]) - s * u[0], double(pose[2, 3]) - s * u[1], double(pose[3, 3]) + c);

    // 3. elbow not below the shoulder
    const auto joints = joint_positions(phi, arm);
    e.below_shoulder = joints[1][2] < joints[0][2] - side_tol * scale;

    // 4. flags; in-plane coordinates relative to the shoulder (x towards the target, z up)
    const double tx = target[0] * std::cos(double(phi[0])) + target[1] * std::sin(double(phi[0]));
    if (std::abs(tx) > side_tol * scale)
        e.wrong_front = sol.flags()[Flags::reach_front_i] != front;

    auto in_plane = [&](const std::array<double, 3>& p) {
        return std::array<double, 2>{(p[0] - joints[0][0]) * u[0] + (p[1] - joints[0][1]) * u[1], p[2] - joints[0][2]};
    };
    const auto el = in_plane(joints[1]), wr = in_plane(joints[2]);
    const double cross = wr[0] * el[1] - wr[1] * el[0];       // > 0: elbow counterclockwise of shoulder->wrist
    const double side_of_up = wr[0] >= 0 ? 1.0 : -1.0;          // "above the line" within the plane
    if (std::abs(cross) > side_tol * scale * scale && std::abs(wr[0]) > side_tol * scale)
        e.wrong_elbow = sol.flags()[Flags::elbow_up_i] != (cross * side_of_up > 0);
    return e;
}

// ------------------------------------------------------------ fixed cases

template<std::floating_point T>
void test_edge_cases(T tol)
{
    const T pi = std::numbers::pi_v<T>;
    const Geometry<T> g{T(0), T(2), T(1), T(0.5), T(0), T(0), {T(0), T(0), T(0)}};
    const auto arm = make_arm(g);
    const auto tool = make_tool(g);

    auto count = [](const arm4R_bnp::Solutions<T>& s) {
        return std::count_if(s.begin(), s.end(), [](const auto& o) { return o.has_value(); });
    };
    auto all_ok = [&](const Geometry<T>& gg, const Arm<T>& a, const Tool<T>& t, const std::array<T, 3>& pos,
                      T theta, const arm4R_bnp::Solutions<T>& s) {
        bool ok = true;
        for (const auto& slot : s) {
            if (!slot) continue;
            auto e = check_solution(gg, a, t, pos, theta, *slot, 1e-6);
            bool finite = true;
            for (T x : slot->angles()) finite = finite && std::isfinite(x);
            ok = ok && finite && e.pos <= double(tol) && e.dir <= double(tol) * 10 && !e.below_shoulder;
        }
        return ok;
    };

    check(count(inverse<T>({T(10), T(0), T(0)}, T(0), arm, tool)) == 0, "edge: target out of reach gives no solution");

    {   // drawing case: pen straight down onto the table in front of the arm
        std::array<T, 3> pos{T(1.5), T(0.5), T(0)};
        auto s = inverse<T>(pos, T(0), arm, tool);
        check(count(s) >= 1, "edge: drawing target on the table has a solution");
        check(all_ok(g, arm, tool, pos, T(0), s), "edge: drawing target round trip");
    }
    {   // target directly above the base axis (base singularity)
        std::array<T, 3> pos{T(0), T(0), T(2)};
        auto s = inverse<T>(pos, T(0), arm, tool);
        check(count(s) >= 1, "edge: target above the base has a solution");
        check(all_ok(g, arm, tool, pos, T(0), s), "edge: target above the base round trip");
    }
    {   // full stretch, horizontal approach: tip at (R1 + R2 + tool, 0, 0)
        std::array<T, 3> pos{T(3.5), T(0), T(0)};
        auto s = inverse<T>(pos, pi / 2, arm, tool);
        check(count(s) >= 1, "edge: full stretch has a solution");
        check(all_ok(g, arm, tool, pos, pi / 2, s), "edge: full stretch round trip");
    }
    {   // lateral offsets: inside the offset circle unreachable, outside fine
        const Geometry<T> go{T(0), T(2), T(1), T(0.5), T(0), T(0), {T(0.1), T(0.05), T(0.05)}};
        const auto armo = make_arm(go);
        check(count(inverse<T>({T(0.1), T(0), T(1)}, T(0), armo, tool)) == 0,
              "edge: target inside the offset circle gives no solution");
        std::array<T, 3> pos{T(1.2), T(-0.7), T(0)};
        auto s = inverse<T>(pos, T(0), armo, tool);
        check(count(s) >= 1, "edge: target with offsets has a solution");
        check(all_ok(go, armo, tool, pos, T(0), s), "edge: target with offsets round trip");
    }
    {   // base height
        const Geometry<T> gh{T(0.4), T(2), T(1), T(0.5), T(0), T(0), {T(0), T(0), T(0)}};
        const auto armh = make_arm(gh);
        std::array<T, 3> pos{T(1.0), T(1.0), T(0.2)};
        auto s = inverse<T>(pos, T(0), armh, tool);
        check(count(s) >= 1, "edge: target with base height has a solution");
        check(all_ok(gh, armh, tool, pos, T(0), s), "edge: base height round trip");
    }
    {   // tool with an offset along its common normal
        const Geometry<T> gt{T(0), T(2), T(1), T(0.5), T(0.1), T(0), {T(0), T(0), T(0)}};
        const auto toolt = make_tool(gt);
        std::array<T, 3> pos{T(1.5), T(0.3), T(0.2)};
        auto s = inverse<T>(pos, T(0.4), arm, toolt);
        check(count(s) >= 1, "edge: tool with common-normal offset has a solution");
        check(all_ok(gt, arm, toolt, pos, T(0.4), s), "edge: tool with common-normal offset round trip");
    }
    {   // tilted tool, wrist point behind the base axis
        std::array<T, 3> pos{T(0.2), T(0), T(1.5)};
        const T theta = T(1.2);
        auto s = inverse<T>(pos, theta, arm, tool);
        check(count(s) >= 1, "edge: wrist behind the base axis has a solution");
        check(all_ok(g, arm, tool, pos, theta, s), "edge: wrist behind the base axis round trip");
    }
}

// ------------------------------------------------------------ randomized test

template<std::floating_point T>
void test_random(int n, T tol, double side_tol, const char* label)
{
    std::mt19937 rng(3);
    std::uniform_real_distribution<double> uni(0.0, 1.0);
    const double pi = std::numbers::pi;

    int bad = 0, solutions = 0, samples = 0;
    double max_pos = 0, max_dir = 0;
    auto fail = [&](const char* what, int i) { if (++bad <= 8) std::printf("  %s sample %d: %s\n", label, i, what); };

    for (int i = 0; i < n; ++i) {
        const Geometry<T> g{
            T(uni(rng) < 0.5 ? 0.0 : 0.5 * uni(rng)),
            T(0.5 + 2.0 * uni(rng)), T(0.5 + 2.0 * uni(rng)),
            T(0.1 + 0.6 * uni(rng)), T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)), T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)),
            {T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)), T(uni(rng) < 0.5 ? 0.0 : 0.1 * uni(rng)), T(0)}};
        const auto arm = make_arm(g);
        const auto tool = make_tool(g);

        // random configuration; sometimes close to full stretch or full fold
        double p2;
        const double u = uni(rng);
        if (u < 0.15)      p2 = std::pow(10.0, -1 - 5 * uni(rng)) * (uni(rng) < 0.5 ? 1 : -1);
        else if (u < 0.3)  p2 = (pi - std::pow(10.0, -1 - 3 * uni(rng))) * (uni(rng) < 0.5 ? 1 : -1);
        else               p2 = -pi + 2 * pi * uni(rng);
        const std::array<T, 4> phi_true{T(-pi + 2 * pi * uni(rng)), T(-pi + 2 * pi * uni(rng)), T(p2),
                                        T(-pi + 2 * pi * uni(rng))};

        // keep configurations the solver accepts: elbow not below the shoulder
        const auto joints = joint_positions(phi_true, arm);
        if (joints[1][2] < joints[0][2]) continue;

        const auto pose = forward(phi_true, arm, tool);
        const std::array<T, 3> pos{pose[1, 0], pose[2, 0], pose[3, 0]};
        if (std::hypot(double(pos[0]), double(pos[1])) <= double(total_offset(g)) * (1 + 1e-6)) continue;
        const T theta = T(approach_angle(pose, double(phi_true[0])));
        ++samples;

        const auto sol = inverse<T>(pos, theta, arm, tool);

        // Near the singularities the problem itself is ill-conditioned; allow a larger error there
        const bool near_singular = std::abs(p2) < 1e-2 || std::abs(std::abs(p2) - pi) < 1e-2;
        const double pos_tol = double(tol) * (near_singular ? 100.0 : 1.0);

        bool found = false;
        for (const auto& slot : sol) {
            if (!slot) continue;
            ++solutions;
            const auto e = check_solution(g, arm, tool, pos, theta, *slot, side_tol);
            max_pos = std::max(max_pos, e.pos);
            max_dir = std::max(max_dir, e.dir);
            if (!(e.pos <= pos_tol))             fail("forward(inverse) misses the target", i);
            if (!(e.dir <= double(tol) * 100))   fail("tool z-axis differs from the approach direction", i);
            if (e.below_shoulder)                fail("elbow below the shoulder", i);
            if (e.wrong_front)                   fail("reach_front flag disagrees with the geometry", i);
            if (e.wrong_elbow)                   fail("elbow_up flag disagrees with the geometry", i);

            bool same = true;
            for (std::size_t k = 0; k < 4; ++k)
                same = same && std::abs(angle_diff(slot->angles()[k], phi_true[k])) < 1e-3;
            found = found || same;
        }
        if (!found && !near_singular) fail("original configuration not among the solutions", i);
    }
    std::printf("%s: %d samples, %d solutions checked, %d failures, "
                "max position error %.3g, max direction error %.3g\n",
                label, samples, solutions, bad, max_pos, max_dir);
    check(bad == 0, label);
}

int main()
{
    test_edge_cases<double>(1e-12);
    test_edge_cases<float>(1e-5f);
    test_random<double>(50000, 1e-12, 1e-9, "double");
    test_random<float>(50000, 1e-5f, 1e-4, "float");
    if (failures == 0) std::printf("All 4R arm kinematics tests passed\n");
    return failures == 0 ? 0 : 1;
}